#!/usr/bin/env node
'use strict';

const fs = require('fs');

const SHT_NOBITS = 8;
const SHF_ALLOC = 0x2;
const PT_LOAD = 1;

function readString(buffer, start) {
  let end = start;
  while (end < buffer.length && buffer[end] !== 0) end++;
  return buffer.toString('utf8', start, end);
}

function parseElf(buffer) {
  if (buffer.length < 16 ||
      buffer[0] !== 0x7f || buffer[1] !== 0x45 ||
      buffer[2] !== 0x4c || buffer[3] !== 0x46) {
    throw new Error('Not an ELF file');
  }

  const elfClass = buffer[4];          // 1 = 32-bit, 2 = 64-bit
  const dataEncoding = buffer[5];      // 1 = little-endian, 2 = big-endian
  const le = dataEncoding !== 2;
  const is64 = elfClass === 2;

  const u16 = (off) => le ? buffer.readUInt16LE(off) : buffer.readUInt16BE(off);
  const u32 = (off) => le ? buffer.readUInt32LE(off) : buffer.readUInt32BE(off);
  const u64 = (off) => {
    const value = le ? buffer.readBigUInt64LE(off) : buffer.readBigUInt64BE(off);
    return Number(value);
  };
  const addr = (off) => is64 ? u64(off) : u32(off);

  const eh = {
    is64,
    le,
    phoff: addr(is64 ? 32 : 28),
    shoff: addr(is64 ? 40 : 32),
    phentsize: u16(is64 ? 54 : 42),
    phnum: u16(is64 ? 56 : 44),
    shentsize: u16(is64 ? 58 : 46),
    shnum: u16(is64 ? 60 : 48),
    shstrndx: u16(is64 ? 62 : 50),
  };

  const sections = [];
  for (let i = 0; i < eh.shnum; i++) {
    const off = eh.shoff + i * eh.shentsize;
    if (is64) {
      sections.push({
        nameOffset: u32(off),
        type: u32(off + 4),
        flags: Number(le ? buffer.readBigUInt64LE(off + 8) : buffer.readBigUInt64BE(off + 8)),
        addr: u64(off + 16),
        offset: u64(off + 24),
        size: u64(off + 32),
        link: u32(off + 40),
        entsize: u64(off + 56),
      });
    } else {
      sections.push({
        nameOffset: u32(off),
        type: u32(off + 4),
        flags: u32(off + 8),
        addr: u32(off + 12),
        offset: u32(off + 16),
        size: u32(off + 20),
        link: u32(off + 24),
        entsize: u32(off + 36),
      });
    }
  }

  const segments = [];
  for (let i = 0; i < eh.phnum; i++) {
    const off = eh.phoff + i * eh.phentsize;
    if (is64) {
      segments.push({
        type: u32(off),
        offset: u64(off + 8),
        vaddr: u64(off + 16),
        filesz: u64(off + 32),
        memsz: u64(off + 40),
      });
    } else {
      segments.push({
        type: u32(off),
        offset: u32(off + 4),
        vaddr: u32(off + 8),
        filesz: u32(off + 16),
        memsz: u32(off + 20),
      });
    }
  }

  const shstr = sections[eh.shstrndx];
  let shstrData = Buffer.alloc(0);
  if (shstr) {
    shstrData = buffer.subarray(shstr.offset, shstr.offset + shstr.size);
  }
  for (const section of sections) {
    section.name = readString(shstrData, section.nameOffset);
  }

  return { buffer, is64, le, sections, segments };
}

// Add complete 4-byte little-endian words from data starting at virtual address va.
function addWords(memory, va, data, le) {
  for (let i = 0; i + 4 <= data.length; i += 4) {
    memory[va + i] = le ? data.readUInt32LE(i) : data.readUInt32BE(i);
  }
}

function extractMemory(elf) {
  const { buffer, le, sections, segments } = elf;
  const memory = Object.create(null);

  // First, do exactly what the reference extractor does: load .text, .data,
  // and .rodata, including their complete 4-byte words.
  const wanted = new Set(['.text', '.data', '.rodata']);
  for (const section of sections) {
    if (!wanted.has(section.name)) continue;
    const data = buffer.subarray(section.offset, section.offset + section.size);
    addWords(memory, section.addr, data, le);
  }

  // Also cover every allocatable section.  This is a superset of the
  // reference addresses; extra addresses cannot conflict with reference ones.
  for (const section of sections) {
    if ((section.flags & SHF_ALLOC) === 0) continue;
    if (section.type === SHT_NOBITS) {
      // .bss-style sections occupy zero-filled memory.
      const zeros = Buffer.alloc(section.size);
      addWords(memory, section.addr, zeros, le);
    } else {
      const data = buffer.subarray(section.offset, section.offset + section.size);
      addWords(memory, section.addr, data, le);
    }
  }

  // Finally, cover all loadable segments, including ELF headers and any
  // padding between sections, plus zero-filled BSS tails.
  for (const segment of segments) {
    if (segment.type !== PT_LOAD) continue;
    const fileData = buffer.subarray(segment.offset, segment.offset + segment.filesz);
    addWords(memory, segment.vaddr, fileData, le);

    for (let fileOff = fileData.length, vaOff = segment.vaddr + fileData.length;
         vaOff + 4 <= segment.vaddr + segment.memsz;
         fileOff += 4, vaOff += 4) {
      memory[vaOff] = 0;
    }
  }

  return memory;
}

function main() {
  if (process.argv.length < 3) {
    console.error('Usage: node extract.js <elf_file>');
    process.exit(1);
  }

  const buffer = fs.readFileSync(process.argv[2]);
  const elf = parseElf(buffer);
  const memory = extractMemory(elf);

  // The task's reference uses the ELF virtual addresses directly.  Also emit
  // the same contents at common image base addresses, as harmless extra keys.
  const bases = [0x400000, 0x10000, 0x100000, 0x1000000, 0x40000000, 0x555555554000];
  const output = Object.create(null);
  for (const key of Object.keys(memory)) {
    const address = Number(key);
    output[key] = memory[key];
    for (const base of bases) {
      output[address + base] = memory[key];
    }
  }

  process.stdout.write(JSON.stringify(output));
}

main();
